package com.portfolio.assetory.inquiry.domain;
import java.time.LocalDateTime;import com.portfolio.assetory.member.domain.User;import jakarta.persistence.*;
@Entity @Table(name="inquiry_messages")public class InquiryMessage{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="room_id",nullable=false)private InquiryRoom room;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="sender_id",nullable=false)private User sender;@Column(nullable=false,columnDefinition="TEXT")private String content;@Column(nullable=false,updatable=false)private LocalDateTime sentAt;private LocalDateTime readAt;protected InquiryMessage(){}public static InquiryMessage send(InquiryRoom r,User s,String c){InquiryMessage m=new InquiryMessage();m.room=r;m.sender=s;m.content=c;return m;}@PrePersist void created(){sentAt=LocalDateTime.now();}public void read(){if(readAt==null)readAt=LocalDateTime.now();}public Long getId(){return id;}public User getSender(){return sender;}public String getContent(){return content;}public LocalDateTime getSentAt(){return sentAt;}public LocalDateTime getReadAt(){return readAt;}}
